eye.eye61Mono:
function eye61Mono(T, Y, x) { // monotone cubic (Fritsch-Carlson) through the keys: no kinks, no ringing between them
  const n = T.length; if (x <= T[0]) return Y[0]; if (x >= T[n - 1]) return Y[n - 1];
  let i = 0; while (x > T[i + 1]) i++;
  const d = k => (Y[k + 1] - Y[k]) / (T[k + 1] - T[k]);
  const m = k => { if (k === 0) return d(0); if (k === n - 1) return d(n - 2); const a = d(k - 1), b = d(k); return a * b <= 0 ? 0 : 3 * (T[k + 1] - T[k - 1]) / ((2 * T[k + 1] - T[k] - T[k - 1]) / a + (T[k + 1] - 2 * T[k] + T[k - 1]) / b); };
  const h = T[i + 1] - T[i], s = (x - T[i]) / h, s2 = s * s, s3 = s2 * s;
  return (2 * s3 - 3 * s2 + 1) * Y[i] + (s3 - 2 * s2 + s) * h * m(i) + (-2 * s3 + 3 * s2) * Y[i + 1] + (s3 - s2) * h * m(i + 1);
}
